fun canTake(input: Int) = !aligned || !seen[input]        // aligned: block an input once its barrier arrived

fun onItem(input: Int, item: Item): List<Item> = when (item) {
    is Record -> listOf(process(item))                     // normal work
    is Barrier -> {
        seen[input] = true
        if (seen.all { it }) {                              // barrier n on every input
            snapshot(item.id, state)                        // state = exactly the records before the barriers
            seen.fill(false)
            listOf(item)                                    // forward one barrier downstream
        } else emptyList()                                  // wait for the other input
    }
    else -> error("unexpected $item")
}

// At-least-once mode: canTake is always true, so the snapshot may include records from after
// the barrier on the fast input; a restore replays and counts them again.
// Unaligned: the barrier overtakes buffered records, which are saved in the snapshot as channel
// state and replayed first on restore; exactly-once, but bigger snapshots.
